/** A provider's mark on a tile, or its name's first letter when there is no mark for it. */
export function ProviderLogo({ id, name }: { id: string; name: string }) {
	const logo = LOGOS[id];
	return (
		<span aria-hidden className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-surface-5 text-foreground shadow-surface-2">
			{logo === undefined ? (
				<span className="text-[13px] font-medium text-muted-foreground">{name.charAt(0).toUpperCase()}</span>
			) : (
				<BrandMark logo={logo} className="size-4" />
			)}
		</span>
	);
}
